#include "WaterWorks.h"
#include "LegacyPowerSlots.h"
#include <cmath>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace aftertaste;using K=MachineKind;using E=EnergyMedium;
static Machine relocated(const Machine& source){auto copy=source;if(copy.kind==K::CoolingPlant)copy.dir=3;if(copy.kind==K::PowerCondenser)copy.dir=1;return copy;}
static int checks=0;static void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
static Factory empty(){Factory f;f.machines.clear();f.energyLinks.clear();f.blueprints.clear();f.water=f.electricity=10000;return f;}
static Machine& add(Factory& f,Position p,K k){Machine m;m.kind=k;initialisePowerDevice(m);return f.machines.emplace(p,m).first->second;}
static void advance(Factory& f,int n){for(int i=0;i<n;i++){f.tick++;f.beginPowerStep();f.finishPowerStep();}}
static Factory bench(){auto f=empty();require(f.stamp(Factory::nuclearLabBlueprint(),{0,0}),"stamp contact bench");f.at({2,0})->power.store[size_t(E::DC)]=300;for(Position p:{Position{1,1},Position{1,2}}){f.at(p)->power.lab.fuel=60;f.at(p)->power.lab.armed=true;}return f;}
int main(int argc,char** argv){try{
 {auto b=Factory::nuclearLabBlueprint();require(b.width==6&&b.height==3&&b.parts.size()==10&&b.links.size()==1&&b.links.front().link.medium==E::AC,"ten apparatus occupy a compact bench with only the export cable");}
 {auto f=empty();add(f,{0,0},K::SolarPanel);auto& inverter=add(f,{0,1},K::Inverter);advance(f,1);require(inverter.power.store[size_t(E::AC)]>0&&f.energyLinks.empty(),"chassis contact supplies DC from a side without an external DC terminal");require(std::abs(f.powerContactFlow({0,0},{0,1},E::DC))>0,"contact telemetry records actual DC transfer");}
 {auto f=empty();add(f,{0,0},K::SolarPanel);auto& inverter=add(f,{1,1},K::Inverter);advance(f,1);require(inverter.power.store[size_t(E::AC)]==0,"diagonal equipment does not make a contact");f.machines.erase({1,1});auto& separated=add(f,{0,2},K::Inverter);advance(f,1);require(separated.power.store[size_t(E::AC)]==0,"one floor-cell gap does not make a contact");}
 {auto f=bench();f.energyLinks.clear();advance(f,48);require(f.at({1,1})->power.lab.heatTotal>500&&f.at({1,2})->power.lab.heatTotal>100,"nuclear bench works without any local cable or pipe");require(f.at({1,2})->power.lab.vacuum>.9&&f.at({2,1})->power.lab.dcTotal>100,"contact pump, quench bath, recorder and calorimeter remain functional");require(f.at({1,0})->power.lab.trials.size()==2,"contact recorder measures both experiments");}
 {auto f=bench();add(f,{9,0},K::GrowLight);for(int x=6;x<=9;x++){PowerLink l;l.medium=E::AC;l.rating=100;l.ports=5;f.energyLinks[{x,0}].push_back(l);}f.tick++;f.beginPowerStep();require(f.powerAvailable({9,0},1),"one export cable powers a remote factory consumer");f.usePower({9,0},1);f.finishPowerStep();require(f.energyLink({7,0},E::AC)->flow>0,"real electricity travels down the factory export cable");f.at({4,0})->enabled=false;f.tick++;f.beginPowerStep();require(!f.powerAvailable({9,0},1),"opening the export switchboard isolates the remote factory");f.finishPowerStep();f.at({4,0})->enabled=true;f.energyLinks.erase({7,0});f.tick++;f.beginPowerStep();require(!f.powerAvailable({9,0},1),"a broken export cable cannot be bypassed by contact at a distance");}
 {auto f=bench();advance(f,24);auto pump=*f.at({0,2});f.machines.erase({0,2});f.machines.emplace(Position{0,3},pump);advance(f,12);require(f.at({1,2})->power.lab.vacuum==0,"moving a support diagonally off the bench disconnects its service");}
 {auto f=empty();auto plan=Factory::rotatedBlueprint(Factory::nuclearLabBlueprint());require(f.stamp(plan,{0,0}),"rotate and stamp contact bench");for(auto& [p,m]:f.machines){if(m.kind==K::BatteryRack)m.power.store[size_t(E::DC)]=300;if(m.kind==K::CuriosityPile||m.kind==K::StarChamber){m.power.lab.fuel=60;m.power.lab.armed=true;}}advance(f,48);double output=0;for(const auto& [p,m]:f.machines)if(m.kind==K::Calorimeter)output+=m.power.lab.dcTotal;require(output>500,"rotated heat ports and shared services still generate actual DC");}
 {auto f=bench();for(auto& [p,m]:f.machines){m.power.store.fill(0);m.power.lab.fuel=0;m.power.lab.armed=false;}f.at({2,0})->power.store[size_t(E::DC)]=12;double loss=0;for(int n=0;n<200;n++){advance(f,1);loss+=f.grid.loss;}double remaining=0,spent=0;for(const auto& [p,m]:f.machines){remaining+=m.power.store[size_t(E::AC)]+m.power.store[size_t(E::DC)];if(m.kind==K::ExperimentConsole||m.kind==K::QuenchBath||m.kind==K::LabVacuumPump)spent+=m.power.lab.inputTotal;}require(spent>0&&remaining<1&&spent+remaining+loss<=12.000001,"contact backplane cannot amplify or indefinitely recycle a finite battery charge");}
 if(argc>1){std::ifstream in(argv[1]);json j;in>>j;auto before=j.at("factory").get<FactoryState>();Factory f;f.storageFile=argv[1];require(f.load(),"load supplied piped laboratory");const std::array<Position,10> old={Position{1,1},{4,1},{7,2},{10,4},{14,4},{1,6},{5,9},{10,9},{14,9},{17,3}};const auto plan=Factory::nuclearLabBlueprint();std::map<Position,Position> moved;for(size_t n=0;n<old.size();n++)moved[{old[n].x-47,old[n].y-2}]={powerRackLabOrigin.x+plan.parts[n].at.x,powerRackLabOrigin.y+plan.parts[n].at.y};
 for(size_t n=0;n<legacyPowerSlots.size();n++)moved[{legacyPowerSlots[n].x-27,legacyPowerSlots[n].y-1}]={powerRackOrigin.x+Factory::powerDistrictBlueprint().parts[n].at.x,powerRackOrigin.y+Factory::powerDistrictBlueprint().parts[n].at.y};
 require(f.machines.size()==before.machines.size()+12,"compaction creates or deletes no equipment");for(const auto& [p,m]:before.machines){Position target=moved.count(p)?moved.at(p):p;require(f.at(target)&&json(*f.at(target))==json(relocated(m)),"all machine settings, live material, fuel and observations survive relocation exactly");}
 require(f.tick==before.tick&&f.water==before.water&&f.chemicals==before.chemicals&&f.electricity==before.electricity&&f.stock==before.stock,"compaction does not spend resources or advance the clock");
 require(f.energyLink({powerRackOrigin.x+10,powerRackOrigin.y+3},E::AC)&&!f.energyLink({-37,1},E::Instrument),"old service loops are removed and the new single export is connected");
 auto file=std::filesystem::temp_directory_path()/"aftertaste-contact-save.json";f.storageFile=file;require(f.save(),"save compact apparatus");Factory again;again.storageFile=file;require(again.load()&&json(static_cast<FactoryState&>(again))==json(static_cast<FactoryState&>(f)),"reload is stable without another move or cartridge grant");std::filesystem::remove(file);
 auto custom=before; // Customize a guaranteed lab wire.
 for(auto& [p,links]:custom.energyLinks)if(p.x==-45&&p.y==-2){links.front().rating+=1;break;}auto snapshot=json(custom);require(!compactLegacyNuclearLabIn(custom)&&json(custom)==snapshot,"custom service ratings block automatic compaction atomically");
 custom=before;custom.machines[nuclearLabOrigin]=Machine{};snapshot=json(custom);require(!compactLegacyNuclearLabIn(custom)&&json(custom)==snapshot,"custom construction is never overwritten by docking the demo");
 }
 std::cout<<"PASS contact power: "<<checks<<" checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL contact power: "<<e.what()<<" (check "<<checks<<")\n";return 1;}}
